alter table questions add column if not exists source_key text;
create unique index if not exists questions_source_key_idx on questions(source_key);

create or replace function fl_norm(p text) returns text language sql immutable as $$
  select btrim(regexp_replace(btrim(regexp_replace(lower(replace(coalesce(p, ''), chr(160), ' ')), '\s+', ' ', 'g')),
         '^выберите (один|все|несколько)[^.]*\.\s*', '', 'i'), ' .;:,')
$$;

