-- категории в настройках: темы документа + категории вопросов, добавленных вручную
update settings set value = (
  select string_agg(c, '|' order by o, c) from (
    select c, min(o) o from (
      select unnest(array[$q$Основы охраны труда в Российской Федерации$q$, $q$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$q$, $q$Безопасные методы и приемы выполнения работ повышенной опасности$q$, $q$Оказание первой помощи пострадавшим$q$]) c, 0 o
      union all select distinct category, 1 from questions
    ) s group by c
  ) t
) where key = 'categories';
